import { ArrowRight, ChevronsUpDown } from 'lucide-react';
import { useMemo, useRef, useState, type ReactNode, type Ref } from 'react';
import { useI18n } from '../../i18n/I18nProvider';
import { cn } from '../../utils/cn';
import { Button } from '../button';
import { Toggle, ToggleGroup } from '../toggle-group';
import { diffLines, diffStats, toJsonText, type DiffLinesOptions } from './diff';
import { collapsibleRanges, pairLines, splitItems, unifiedItems, type ViewLine } from './diff-view';
import { diffViewerVariants } from './diff-viewer.variants';

export type DiffMode = 'split' | 'unified';

export interface DiffViewerProps extends DiffLinesOptions {
  /** The old text, or any JSON value when `format="json"`. */
  oldValue: unknown;
  /** The new text, or any JSON value when `format="json"`. */
  newValue: unknown;
  /** `json` pretty-prints both sides with sorted keys before diffing (strings are parsed). */
  format?: 'text' | 'json';
  /** Layout (controlled). */
  mode?: DiffMode;
  defaultMode?: DiffMode;
  onModeChange?: (mode: DiffMode) => void;
  /** Show the split / unified switch (default true). */
  showModeToggle?: boolean;
  /** File or version labels for each side, e.g. "config.yaml · v3". */
  oldLabel?: ReactNode;
  newLabel?: ReactNode;
  /** Unchanged lines kept around each change; longer runs collapse behind "Expand N lines". `Infinity` shows everything. Default 3. */
  context?: number;
  /** Highlight changed words inside paired lines (default true). */
  wordDiff?: boolean;
  showLineNumbers?: boolean;
  /** Max height of the scrolling body (any CSS length). */
  maxHeight?: number | string;
  /** Accessible name of the scrolling region. Defaults to "Diff". */
  'aria-label'?: string;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

/**
 * Compares two texts (or JSON values) line by line, in split or unified layout. Changed lines
 * carry +/− markers and screen-reader text, not just a tint; paired lines get word-level
 * highlights; long unchanged runs collapse behind an "Expand N lines" button.
 */
export function DiffViewer({
  oldValue,
  newValue,
  format = 'text',
  mode: modeProp,
  defaultMode = 'unified',
  onModeChange,
  showModeToggle = true,
  oldLabel,
  newLabel,
  context = 3,
  wordDiff = true,
  showLineNumbers = true,
  ignoreWhitespace,
  ignoreCase,
  maxHeight,
  'aria-label': ariaLabel,
  className,
  ref,
}: DiffViewerProps) {
  const { t } = useI18n();
  const [innerMode, setInnerMode] = useState<DiffMode>(defaultMode);
  const [expanded, setExpanded] = useState<ReadonlySet<number>>(() => new Set());
  const bodyRef = useRef<HTMLDivElement>(null);
  const mode = modeProp ?? innerMode;
  const s = diffViewerVariants();

  const lines = useMemo(() => {
    const toText = (v: unknown) => (format === 'json' ? toJsonText(v) : typeof v === 'string' ? v : String(v ?? ''));
    return diffLines(toText(oldValue), toText(newValue), { ignoreWhitespace, ignoreCase });
  }, [oldValue, newValue, format, ignoreWhitespace, ignoreCase]);
  const view = useMemo(() => pairLines(lines, wordDiff).lines, [lines, wordDiff]);
  const stats = useMemo(() => diffStats(lines), [lines]);
  const hidden = useMemo(() => collapsibleRanges(lines, context).filter(([start]) => !expanded.has(start)), [lines, context, expanded]);
  const items = useMemo(() => (mode === 'split' ? splitItems(view, hidden) : unifiedItems(view, hidden)), [mode, view, hidden]);

  const digits = String(Math.max(1, ...lines.map((l) => Math.max(l.oldLine ?? 0, l.newLine ?? 0)))).length;
  const numberStyle = { minWidth: `calc(${digits}ch + 1rem)` };

  const setMode = (next: DiffMode) => {
    setInnerMode(next);
    onModeChange?.(next);
  };

  const expand = (start: number) => {
    setExpanded((prev) => new Set(prev).add(start));
    bodyRef.current?.focus();
  };

  const srPrefix = (line: ViewLine) =>
    line.type === 'added' ? t('diff.addedLine', { line: line.newLine ?? '' }) : line.type === 'removed' ? t('diff.removedLine', { line: line.oldLine ?? '' }) : '';

  const code = (line: ViewLine) => {
    const v = diffViewerVariants({ type: line.type });
    const prefix = srPrefix(line);
    return (
      <span className={s.code()}>
        {prefix && <span className="sr-only">{prefix} </span>}
        {line.words
          ? line.words.map((w, i) =>
              w.changed ? (
                <span key={i} className={v.word()} data-changed="">
                  {w.text}
                </span>
              ) : (
                w.text
              ),
            )
          : line.text || '​'}
      </span>
    );
  };

  const marker = (line: ViewLine) => (
    <span aria-hidden className={diffViewerVariants({ type: line.type }).marker()}>
      {line.type === 'added' ? '+' : line.type === 'removed' ? '−' : ' '}
    </span>
  );

  const number = (value: number | undefined, line: ViewLine) =>
    showLineNumbers ? (
      <span aria-hidden className={diffViewerVariants({ type: line.type }).number()} style={numberStyle}>
        {value ?? ''}
      </span>
    ) : (
      <span aria-hidden />
    );

  // The new side of an unchanged row repeats the old one, so screen readers skip it.
  const half = (line: ViewLine | undefined, side: 'old' | 'new') => {
    if (!line) return <div className={cn(s.half(), s.empty())} />;
    const type = line.type;
    return (
      <div className={diffViewerVariants({ type }).half()} data-type={type} aria-hidden={side === 'new' && type === 'unchanged' ? true : undefined}>
        {number(side === 'old' ? line.oldLine : line.newLine, line)}
        {marker(line)}
        {code(line)}
      </div>
    );
  };

  const hasChanges = stats.added + stats.removed > 0;
  const labels = oldLabel != null || newLabel != null;

  return (
    <div ref={ref} className={cn(s.root(), className)} data-mode={mode}>
      <div className={s.header()}>
        <div className={s.labels()}>
          {labels && mode === 'unified' && (
            <>
              <span className={s.label()}>
                <span className="sr-only">{t('diff.old')}: </span>
                {oldLabel}
              </span>
              <ArrowRight size={13} aria-hidden className={s.arrow()} />
              <span className={s.label()}>
                <span className="sr-only">{t('diff.new')}: </span>
                {newLabel}
              </span>
            </>
          )}
        </div>
        <div className={s.stats()}>
          <span className={s.statAdded()}>
            <span aria-hidden>+{stats.added}</span>
            <span className="sr-only">{t('diff.additions', { count: stats.added })}</span>
          </span>
          <span className={s.statRemoved()}>
            <span aria-hidden>−{stats.removed}</span>
            <span className="sr-only">{t('diff.deletions', { count: stats.removed })}</span>
          </span>
        </div>
        {showModeToggle && (
          <ToggleGroup aria-label={t('diff.view')} size="sm" value={[mode]} onValueChange={(v) => v[0] && setMode(v[0] as DiffMode)}>
            <Toggle value="unified">{t('diff.unified')}</Toggle>
            <Toggle value="split">{t('diff.split')}</Toggle>
          </ToggleGroup>
        )}
      </div>
      {mode === 'split' && labels && (
        <div className={s.columns()}>
          <span className={s.column()}>
            <span className="sr-only">{t('diff.old')}: </span>
            {oldLabel}
          </span>
          <span className={s.column()}>
            <span className="sr-only">{t('diff.new')}: </span>
            {newLabel}
          </span>
        </div>
      )}
      <div
        ref={bodyRef}
        role="region"
        aria-label={ariaLabel ?? t('diff.label')}
        tabIndex={0}
        className={s.body()}
        style={maxHeight != null ? { maxHeight } : undefined}
      >
        {!hasChanges && <p className={s.noChanges()}>{t('diff.noChanges')}</p>}
        {items.map((item) => {
          if (item.kind === 'collapsed') {
            const start = Number(item.key.slice(1));
            return (
              <div key={item.key} className={s.collapsed()}>
                <Button variant="ghost" size="sm" icon={ChevronsUpDown} className="h-6 font-sans text-[12px]" onClick={() => expand(start)}>
                  {t('diff.expand', { count: item.count })}
                </Button>
              </div>
            );
          }
          if (item.line) {
            const line = item.line;
            return (
              <div key={item.key} className={cn(s.row(), s.unifiedRow(), diffViewerVariants({ type: line.type }).row())} data-type={line.type}>
                {number(line.oldLine, line)}
                {number(line.newLine, line)}
                {marker(line)}
                {code(line)}
              </div>
            );
          }
          const isUnchanged = item.left?.type === 'unchanged';
          return (
            <div key={item.key} className={cn(s.row(), s.splitRow())} data-type={isUnchanged ? 'unchanged' : 'changed'}>
              {half(item.left, 'old')}
              {half(item.right, 'new')}
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { diffWords, worthWordDiff, type DiffLine, type WordSegment } from './diff';

/** A line plus its word segments when it is paired with a counterpart. */
export interface ViewLine extends DiffLine {
  index: number;
  words?: WordSegment[];
}

/** One rendered row: a line pair (split), a single line (unified) or a collapsed run. */
export type ViewItem =
  | { kind: 'lines'; key: string; left?: ViewLine; right?: ViewLine; line?: ViewLine }
  | { kind: 'collapsed'; key: string; count: number };

/** Adds word segments to removed/added lines paired by position within each changed block. */
export function pairLines(lines: readonly DiffLine[], wordDiff: boolean): { lines: ViewLine[]; pairs: Map<number, number> } {
  const out: ViewLine[] = lines.map((line, index) => ({ ...line, index }));
  const pairs = new Map<number, number>();
  let i = 0;
  while (i < out.length) {
    if (out[i]!.type === 'unchanged') {
      i++;
      continue;
    }
    const removed: number[] = [];
    const added: number[] = [];
    while (i < out.length && out[i]!.type === 'removed') removed.push(i++);
    while (i < out.length && out[i]!.type === 'added') added.push(i++);
    for (let p = 0; p < Math.min(removed.length, added.length); p++) {
      const r = removed[p]!;
      const a = added[p]!;
      pairs.set(r, a);
      if (!wordDiff) continue;
      const segments = diffWords(out[r]!.text, out[a]!.text);
      if (!worthWordDiff(segments)) continue;
      out[r] = { ...out[r]!, words: segments.old };
      out[a] = { ...out[a]!, words: segments.new };
    }
  }
  return { lines: out, pairs };
}

/**
 * Ranges of unchanged lines to hide: runs longer than `context` lines on each side of a change
 * (only one side at the start or end of the file). Returns [start, end) index ranges.
 */
export function collapsibleRanges(lines: readonly DiffLine[], context: number, minHidden = 2): Array<[number, number]> {
  const ranges: Array<[number, number]> = [];
  if (!Number.isFinite(context)) return ranges;
  let i = 0;
  while (i < lines.length) {
    if (lines[i]!.type !== 'unchanged') {
      i++;
      continue;
    }
    const start = i;
    while (i < lines.length && lines[i]!.type === 'unchanged') i++;
    const from = start === 0 ? start : start + context;
    const to = i === lines.length ? i : i - context;
    if (to - from >= minHidden) ranges.push([from, to]);
  }
  return ranges;
}

/** Rows for the unified view. */
export function unifiedItems(lines: readonly ViewLine[], hidden: ReadonlyArray<[number, number]>): ViewItem[] {
  const items: ViewItem[] = [];
  let r = 0;
  for (let i = 0; i < lines.length; i++) {
    const range = hidden[r];
    if (range && i === range[0]) {
      items.push({ kind: 'collapsed', key: `c${range[0]}`, count: range[1] - range[0] });
      i = range[1] - 1;
      r++;
      continue;
    }
    items.push({ kind: 'lines', key: `l${i}`, line: lines[i]! });
  }
  return items;
}

/** Rows for the split view: unchanged lines on both sides, removed left and added right. */
export function splitItems(lines: readonly ViewLine[], hidden: ReadonlyArray<[number, number]>): ViewItem[] {
  const items: ViewItem[] = [];
  let r = 0;
  let i = 0;
  while (i < lines.length) {
    const range = hidden[r];
    if (range && i === range[0]) {
      items.push({ kind: 'collapsed', key: `c${range[0]}`, count: range[1] - range[0] });
      i = range[1];
      r++;
      continue;
    }
    const line = lines[i]!;
    if (line.type === 'unchanged') {
      items.push({ kind: 'lines', key: `l${i}`, left: line, right: line });
      i++;
      continue;
    }
    const removed: ViewLine[] = [];
    const added: ViewLine[] = [];
    while (i < lines.length && lines[i]!.type === 'removed') removed.push(lines[i++]!);
    while (i < lines.length && lines[i]!.type === 'added') added.push(lines[i++]!);
    for (let p = 0; p < Math.max(removed.length, added.length); p++) {
      const left = removed[p];
      const right = added[p];
      items.push({ kind: 'lines', key: `p${(left ?? right)!.index}`, left, right });
    }
  }
  return items;
}

import { tv, type VariantProps } from '../../utils/tv';

/** Line styling never relies on colour alone: every changed line also has a +/− marker and screen-reader text. */
export const diffViewerVariants = tv({
  slots: {
    root: 'flex min-w-0 flex-col overflow-hidden rounded-lg border border-border bg-card text-foreground',
    header: 'flex flex-wrap items-center gap-x-3 gap-y-2 border-b border-border px-3 py-2',
    labels: 'flex min-w-0 flex-1 items-center gap-2 font-mono text-[12px] text-muted-foreground',
    label: 'truncate text-foreground',
    arrow: 'shrink-0 rtl:-scale-x-100',
    stats: 'flex shrink-0 items-center gap-2 font-mono text-[12px] font-medium',
    statAdded: 'text-success-text',
    statRemoved: 'text-destructive-text',
    columns: 'grid grid-cols-2 border-b border-border font-mono text-[11.5px] text-muted-foreground',
    column: 'truncate px-3 py-1.5 first:border-e first:border-border',
    body: 'overflow-auto font-mono text-[12px] leading-5 outline-none focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-focus-ring',
    row: 'grid min-w-0',
    unifiedRow: 'grid-cols-[auto_auto_1.25rem_minmax(0,1fr)]',
    splitRow: 'grid-cols-2',
    half: 'grid min-w-0 grid-cols-[auto_1.25rem_minmax(0,1fr)] first:border-e first:border-border',
    number: 'px-2 text-end text-muted-foreground tabular-nums select-none',
    marker: 'text-center select-none',
    code: 'min-w-0 pe-3 break-words whitespace-pre-wrap',
    word: 'rounded-sm',
    empty: 'bg-secondary/40',
    collapsed: 'flex items-center border-y border-border bg-secondary/40 px-1 py-0.5',
    noChanges: 'px-3 py-2 font-sans text-[12.5px] text-muted-foreground',
  },
  variants: {
    type: {
      unchanged: {},
      added: { row: 'bg-success/10', half: 'bg-success/10', number: 'bg-success/15', marker: 'text-success-text', word: 'bg-success/30' },
      removed: { row: 'bg-destructive/10', half: 'bg-destructive/10', number: 'bg-destructive/15', marker: 'text-destructive-text', word: 'bg-destructive/30' },
    },
  },
  defaultVariants: { type: 'unchanged' },
});

export type DiffViewerVariantProps = VariantProps<typeof diffViewerVariants>;

/**
 * Line and word diffs (Myers O(ND), no dependencies) plus the view model DiffViewer renders:
 * hunks with collapsed unchanged runs, and removed/added line pairs for split view and word
 * highlights.
 */

export type DiffLineType = 'unchanged' | 'added' | 'removed';

export interface DiffLine {
  type: DiffLineType;
  text: string;
  /** 1-based line number in the old text (unchanged and removed lines). */
  oldLine?: number;
  /** 1-based line number in the new text (unchanged and added lines). */
  newLine?: number;
}

export interface DiffLinesOptions {
  /** Treat lines that differ only in whitespace as unchanged (the new text is shown). */
  ignoreWhitespace?: boolean;
  /** Compare case-insensitively. */
  ignoreCase?: boolean;
}

type Edit = { op: '=' | '-' | '+'; a: number; b: number };

/** Above this many trace cells, Myers gives up and reports the middle as replaced. */
const MAX_TRACE_CELLS = 20_000_000;

/** Shortest edit script between two id sequences (Myers' greedy algorithm with backtracking). */
function myers(a: Int32Array, b: Int32Array): Edit[] {
  let start = 0;
  let endA = a.length;
  let endB = b.length;
  while (start < endA && start < endB && a[start] === b[start]) start++;
  while (endA > start && endB > start && a[endA - 1] === b[endB - 1]) {
    endA--;
    endB--;
  }
  const head: Edit[] = [];
  for (let i = 0; i < start; i++) head.push({ op: '=', a: i, b: i });
  const tail: Edit[] = [];
  for (let i = 0; endA + i < a.length; i++) tail.push({ op: '=', a: endA + i, b: endB + i });

  const n = endA - start;
  const m = endB - start;
  const max = n + m;
  const off = max + 1;
  const middle: Edit[] = [];
  if (n === 0 || m === 0) {
    for (let i = 0; i < n; i++) middle.push({ op: '-', a: start + i, b: -1 });
    for (let j = 0; j < m; j++) middle.push({ op: '+', a: -1, b: start + j });
    return [...head, ...middle, ...tail];
  }

  const v = new Int32Array(2 * max + 2);
  const trace: Int32Array[] = [];
  let found = false;
  for (let d = 0; d <= max && !found; d++) {
    if ((d + 1) * v.length > MAX_TRACE_CELLS) break;
    trace.push(v.slice());
    for (let k = -d; k <= d; k += 2) {
      let x = k === -d || (k !== d && v[k - 1 + off]! < v[k + 1 + off]!) ? v[k + 1 + off]! : v[k - 1 + off]! + 1;
      let y = x - k;
      while (x < n && y < m && a[start + x] === b[start + y]) {
        x++;
        y++;
      }
      v[k + off] = x;
      if (x >= n && y >= m) {
        found = true;
        break;
      }
    }
  }

  if (!found) {
    for (let i = 0; i < n; i++) middle.push({ op: '-', a: start + i, b: -1 });
    for (let j = 0; j < m; j++) middle.push({ op: '+', a: -1, b: start + j });
    return [...head, ...middle, ...tail];
  }

  let x = n;
  let y = m;
  for (let d = trace.length - 1; d >= 0; d--) {
    const vd = trace[d]!;
    const k = x - y;
    const prevK = k === -d || (k !== d && vd[k - 1 + off]! < vd[k + 1 + off]!) ? k + 1 : k - 1;
    const prevX = vd[prevK + off]!;
    const prevY = prevX - prevK;
    while (x > prevX && y > prevY) {
      x--;
      y--;
      middle.push({ op: '=', a: start + x, b: start + y });
    }
    if (d > 0) {
      if (x === prevX) middle.push({ op: '+', a: -1, b: start + y - 1 });
      else middle.push({ op: '-', a: start + x - 1, b: -1 });
    }
    x = prevX;
    y = prevY;
  }
  middle.reverse();
  return [...head, ...middle, ...tail];
}

/** Maps each distinct (normalised) token to an integer so comparisons are cheap. */
function toIds(lists: [string[], string[]], normalise: (s: string) => string): [Int32Array, Int32Array] {
  const ids = new Map<string, number>();
  const encode = (list: string[]) =>
    Int32Array.from(list, (item) => {
      const key = normalise(item);
      let id = ids.get(key);
      if (id === undefined) {
        id = ids.size;
        ids.set(key, id);
      }
      return id;
    });
  return [encode(lists[0]), encode(lists[1])];
}

/** Splits text into lines; a single trailing newline does not add an empty line. */
export function splitLines(text: string): string[] {
  if (!text) return [];
  const lines = text.split(/\r?\n/);
  if (lines[lines.length - 1] === '') lines.pop();
  return lines;
}

/**
 * Line diff of two texts. Within each changed block, removed lines come before added ones.
 * Pure: safe to call on the server or in a worker.
 */
export function diffLines(oldText: string, newText: string, { ignoreWhitespace = false, ignoreCase = false }: DiffLinesOptions = {}): DiffLine[] {
  const a = splitLines(oldText);
  const b = splitLines(newText);
  const normalise = (s: string) => {
    let out = ignoreWhitespace ? s.replace(/\s+/g, ' ').trim() : s;
    if (ignoreCase) out = out.toLowerCase();
    return out;
  };
  const [ia, ib] = toIds([a, b], normalise);
  const out: DiffLine[] = [];
  let removed: DiffLine[] = [];
  let added: DiffLine[] = [];
  const flush = () => {
    out.push(...removed, ...added);
    removed = [];
    added = [];
  };
  for (const e of myers(ia, ib)) {
    if (e.op === '=') {
      flush();
      out.push({ type: 'unchanged', text: b[e.b]!, oldLine: e.a + 1, newLine: e.b + 1 });
    } else if (e.op === '-') removed.push({ type: 'removed', text: a[e.a]!, oldLine: e.a + 1 });
    else added.push({ type: 'added', text: b[e.b]!, newLine: e.b + 1 });
  }
  flush();
  return out;
}

export interface WordSegment {
  text: string;
  changed: boolean;
}

const WORD_RE = /\s+|[\p{L}\p{N}_]+|[^\s\p{L}\p{N}_]/gu;

/** Word-level diff of two lines: the segments of each side, with changed runs marked. */
export function diffWords(oldLine: string, newLine: string): { old: WordSegment[]; new: WordSegment[] } {
  const a = oldLine.match(WORD_RE) ?? [];
  const b = newLine.match(WORD_RE) ?? [];
  const [ia, ib] = toIds([a, b], (s) => s);
  const left: WordSegment[] = [];
  const right: WordSegment[] = [];
  const push = (list: WordSegment[], text: string, changed: boolean) => {
    const last = list[list.length - 1];
    if (last && last.changed === changed) last.text += text;
    else list.push({ text, changed });
  };
  for (const e of myers(ia, ib)) {
    if (e.op === '=') {
      push(left, a[e.a]!, false);
      push(right, b[e.b]!, false);
    } else if (e.op === '-') push(left, a[e.a]!, true);
    else push(right, b[e.b]!, true);
  }
  return { old: left, new: right };
}

/** True when two lines share enough text for word highlights to help (≥ 40% unchanged). */
export function worthWordDiff(segments: { old: WordSegment[]; new: WordSegment[] }): boolean {
  const same = (list: WordSegment[]) => list.reduce((n, s) => n + (s.changed ? 0 : s.text.trim().length), 0);
  const total = (list: WordSegment[]) => list.reduce((n, s) => n + s.text.trim().length, 0);
  const shorter = Math.min(total(segments.old), total(segments.new));
  return shorter > 0 && Math.min(same(segments.old), same(segments.new)) / shorter >= 0.4;
}

function sortKeys(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sortKeys);
  if (value && typeof value === 'object' && Object.getPrototypeOf(value) === Object.prototype) {
    const out: Record<string, unknown> = {};
    for (const key of Object.keys(value).sort()) out[key] = sortKeys((value as Record<string, unknown>)[key]);
    return out;
  }
  return value;
}

/** Pretty-printed JSON (2 spaces) with object keys sorted, so key order never shows as a change. */
export function stableStringify(value: unknown): string {
  if (value === undefined) return '';
  return JSON.stringify(sortKeys(value), null, 2) ?? '';
}

/** Diff of two JSON values (or JSON strings), compared as stable pretty-printed text. */
export function diffJson(oldValue: unknown, newValue: unknown, options?: DiffLinesOptions): DiffLine[] {
  return diffLines(toJsonText(oldValue), toJsonText(newValue), options);
}

/** A value as stable JSON text; strings are parsed first and left as they are if not JSON. */
export function toJsonText(value: unknown): string {
  if (typeof value !== 'string') return stableStringify(value);
  try {
    return stableStringify(JSON.parse(value));
  } catch {
    return value;
  }
}

/** Counts of added and removed lines. */
export function diffStats(lines: readonly DiffLine[]): { added: number; removed: number } {
  let added = 0;
  let removed = 0;
  for (const line of lines) {
    if (line.type === 'added') added++;
    else if (line.type === 'removed') removed++;
  }
  return { added, removed };
}

